/*
 Problem: 63. Unique Paths II
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 11.8 MB (54.64%)
 Tags: Array, Dynamic Programming, Matrix
*/
class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& a) {
        int n = a.size(), m = a[0].size();

        vector<vector<int>> dp(n, vector<int>(m, 0));

        if (a[0][0]) return 0;

        dp[0][0] = 1;

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j) {
                if (a[i][j]) continue;

                if (i > 0 && !a[i - 1][j])
                    dp[i][j] += dp[i - 1][j];

                if (j > 0 && !a[i][j - 1])
                    dp[i][j] += dp[i][j - 1];
            }

        return dp[n - 1][m - 1];        
    }
};
